// Create a single contiguous allocation that holds both the serialized-pointer
// object (sptr as the base) and the target pointer region to guarantee a
// non-negative, 32-bit representable offset.
// Choose sizes using fuzzable integers with an upper bound to keep allocations small.
unsigned int extra = *FUZZ_PARAM(unsigned int) % 1024; // <= 1023 bytes
size_t base_size = sizeof(*((nxt_unit_sptr_t*)nullptr));
size_t total_size = base_size + 1 + extra; // at least one byte after sptr
uint8_t *mem = (uint8_t*)::operator new(total_size);
// Place sptr at the beginning of the block so (ptr - sptr_base) is non-negative.
nxt_unit_sptr_t *sptr = (nxt_unit_sptr_t*)mem;
// Choose an in-block target address at a non-negative offset within [0, total_size - 1].
unsigned int off = 0;
if (total_size > 0) {
    off = (unsigned int)(*FUZZ_PARAM(unsigned int) % (unsigned int)total_size);
}
void *target = (void*)(mem + off);
// Optionally touch the target location to ensure the memory is accessible for later use.
mem[off] ^= 0xAA;
// Call the target function under test.
nxt_unit_sptr_set(sptr, target);
// Persist metadata for downstream stubs to validate/get the pointer later.
FUZZ_SET_ATTR_PTR(sptr, "mem_base", mem);
FUZZ_SET_ATTR_INT(sptr, "mem_size", (int)total_size);
FUZZ_SET_ATTR_INT(sptr, "offset", (int)off);
FUZZ_SET_ATTR_INT(sptr, "is_set", 1);
// Expose sptr as an output so subsequent calls (e.g., nxt_unit_sptr_get) can consume it.

// Validate that this sptr was previously initialized by nxt_unit_sptr_set stub.
void *mem_base = FUZZ_GET_ATTR_PTR(sptr, "mem_base");
int mem_size = FUZZ_GET_ATTR_INT(sptr, "mem_size");
int off = FUZZ_GET_ATTR_INT(sptr, "offset");
int is_set = FUZZ_GET_ATTR_INT(sptr, "is_set");
if (!mem_base || mem_size <= 0 || off < 0 || off >= mem_size || !is_set) {
    // Missing or inconsistent attributes; cannot safely get.
    FUZZ_BAIL();
}
// Call the target function under test to reconstruct the absolute pointer.
void *recovered = nxt_unit_sptr_get(sptr);
// Property: recovered must fall within the allocation bounds and match base+offset.
uint8_t *base = (uint8_t*)mem_base;
uint8_t *expect = base + off;
FUZZ_ASSERT(recovered == (void*)expect, "nxt_unit_sptr_get did not match expected base+offset");
FUZZ_ASSERT((uint8_t*)recovered >= base && (uint8_t*)recovered < base + mem_size,
            "recovered pointer out of allocation bounds");
// Light-touch read within bounds to exercise the reconstructed pointer without UB.
volatile uint8_t byte = *((uint8_t*)recovered);
(void)byte;
// Keep sptr alive for future operations by returning it as an output.

// Generate a random byte string and choose a valid length to hash.
std::string name_bytes = FUZZ_PARAM_STR();
size_t max_len = name_bytes.size();
// Exercise both empty and non-empty paths; cap size to keep it small.
size_t name_length = (max_len == 0) ? 0 : (*FUZZ_PARAM(unsigned int) % (max_len + 1));

// Call the target function. name does not need to be NUL-terminated; pass raw data pointer.
uint16_t h = nxt_unit_field_hash(name_bytes.data(), name_length);

// Property sanity: hashing should be defined for any length, including zero.
FUZZ_ASSERT(true, "nxt_unit_field_hash should not have preconditions beyond buffer/length");

// Validation summary: ensured the buffer has at least name_length bytes and exercised zero/non-zero lengths. No persistent objects to output.

// port_id must be a valid writable pointer supplied by the fuzzer runtime.
// Generate pid and 16-bit id within valid ranges.
pid_t pid = static_cast<pid_t>(*FUZZ_PARAM(int));
uint16_t id = static_cast<uint16_t>(*FUZZ_PARAM(unsigned int));

// Initialize the structure and compute its hash.
nxt_unit_port_id_init(port_id, pid, id);

// Postconditions: fields pid and id should match inputs.
FUZZ_ASSERT(port_id->pid == pid, "port_id.pid must equal the input pid");
FUZZ_ASSERT(port_id->id == id, "port_id.id must equal the input id");

// Note: hash field is implementation-defined; we do not assert its exact value.

// Validation summary: supplied valid writable struct, constrained id to 16 bits, and asserted pid/id were set. The initialized port_id is returned as an output for reuse.

// Retain the WebSocket frame and track a logical refcount via attributes.
// If this is the first time we see the frame, assume a baseline refcount of 1 (library-owned).
int ref = FUZZ_GET_ATTR_INT(ws, "ws_ref");
if (ref == 0) {
    ref = 1; // baseline ownership prior to our explicit retains
}

// Call the target function which should increment the library's retain count.
int rc = nxt_unit_websocket_retain(ws);
(void)rc; // rc may be implementation-defined; we don't assert it here.

// Mirror the retain in our attribute-tracked refcount.
FUZZ_SET_ATTR_INT(ws, "ws_ref", ref + 1);

// Return ws for further use.

// Release one retain on the WebSocket frame.
// To ensure we don't return a freed object, enforce refcount >= 2 before calling done:
//   - One for baseline/library ownership, and at least one extra retained by us.
int ref = FUZZ_GET_ATTR_INT(ws, "ws_ref");
if (ref < 2) { FUZZ_BAIL(); }

// Call the target function to drop one retain.
nxt_unit_websocket_done(ws);

// Mirror the release in our attribute-tracked refcount and keep the object in the pool.
FUZZ_SET_ATTR_INT(ws, "ws_ref", ref - 1);

