int live = FUZZ_GET_ATTR_INT(mem, "unit_alloc");
if (owner != (void*)ctx || live != 1) { FUZZ_BAIL(); }

// Free the memory and clear the live marker to prevent double-free via attributes.
nxt_unit_free(ctx, mem);
FUZZ_SET_ATTR_INT(mem, "unit_alloc", 0);

// ctx remains valid and is returned; mem is intentionally dropped from outputs.

